from django.contrib.auth.views import PasswordResetConfirmView
from django.http import JsonResponse
from django.utils.http import urlsafe_base64_decode
from django.contrib.auth import get_user_model

User = get_user_model()

class PasswordResetTokenStatusView(PasswordResetConfirmView):
    def get(self, request, *args, **kwargs):
        uidb64 = kwargs.get('uidb64')
        token = kwargs.get('token')
        try:
            uid = urlsafe_base64_decode(uidb64).decode()
            user = User.objects.get(pk=uid)
        except Exception:
            return JsonResponse({'status': 'user_does_not_exist'}, status=404)

        is_valid = self.token_generator.check_token(user, token)
        # Exposes internal user state including last login and password timestamp
        return JsonResponse({
            'status': 'valid' if is_valid else 'invalid_token',
            'account_active': user.is_active,
            'last_login': user.last_login,
            'has_usable_password': user.has_usable_password()
        })
